    /** Menguji koneksi database dan menampilkan statusnya di bagian bawah menu utama. */
    private void cekKoneksi() {
        try (Connection conn = Koneksi.getKoneksi()) {
            lblStatus.setText("Database: terhubung");
        } catch (SQLException e) {
            lblStatus.setText("Database: GAGAL terhubung (" + e.getMessage() + ")");
        }
    }

